#include <vector>
#include <set>
#include <tuple>

class Solution {
public:
    int minGenerations(std::vector<std::vector<int>>& points, std::vector<int>& target) {
        std::tuple<int, int, int> tgt = {target[0], target[1], target[2]};
        std::set<std::tuple<int, int, int>> curSet;
        std::vector<std::tuple<int, int, int>> allPoints;
        for (const auto& p : points) {
            auto pt = std::make_tuple(p[0], p[1], p[2]);
            if (!curSet.count(pt)) {
                curSet.insert(pt);
                allPoints.push_back(pt);
            }
        }
        if (curSet.count(tgt)) return 0;
        for (int gen = 1; gen < 10; ++gen) {
            std::vector<std::tuple<int, int, int>> newPoints;
            int m = allPoints.size();
            for (int i = 0; i < m; ++i) {
                const auto& [x1, y1, z1] = allPoints[i];
                for (int j = i + 1; j < m; ++j) {
                    const auto& [x2, y2, z2] = allPoints[j];
                    auto mid = std::make_tuple((x1 + x2) / 2, (y1 + y2) / 2, (z1 + z2) / 2);
                    if (mid == tgt) return gen;
                    if (!curSet.count(mid)) {
                        curSet.insert(mid);
                        newPoints.push_back(mid);
                    }
                }
            }
            if (newPoints.empty()) break;
            allPoints.insert(allPoints.end(), newPoints.begin(), newPoints.end());
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minGenerations(int[][] points, int[] target) {
        String tgt = target[0] + "," + target[1] + "," + target[2];
        Set<String> curSet = new HashSet<>();
        List<int[]> allPoints = new ArrayList<>();
        for (int[] p : points) {
            String key = p[0] + "," + p[1] + "," + p[2];
            if (curSet.add(key)) {
                allPoints.add(p);
            }
        }
        if (curSet.contains(tgt)) return 0;
        for (int gen = 1; gen < 10; gen++) {
            List<int[]> newPoints = new ArrayList<>();
            int m = allPoints.size();
            for (int i = 0; i < m; i++) {
                int[] p1 = allPoints.get(i);
                for (int j = i + 1; j < m; j++) {
                    int[] p2 = allPoints.get(j);
                    int[] mid = new int[]{(p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2, (p1[2] + p2[2]) / 2};
                    String key = mid[0] + "," + mid[1] + "," + mid[2];
                    if (key.equals(tgt)) return gen;
                    if (curSet.add(key)) {
                        newPoints.add(mid);
                    }
                }
            }
            if (newPoints.isEmpty()) break;
            allPoints.addAll(newPoints);
        }
        return -1;
    }
}

